<?php
require_once 'functions.php'; require_role(['admin','staff']); $u=current_user();
if($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $id=(int)($_POST['appointment_id']??0);$action=$_POST['action']??'';
 $s=$pdo->prepare('SELECT * FROM appointments WHERE id=?');$s->execute([$id]);$a=$s->fetch();
 if(!$a){flash('Appointment not found.','error');go('manage.php');}
 if($action==='approve' && $u['role']==='admin' && $a['status']==='Pending') {
   try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT COALESCE(MAX(queue_number),0)+1 FROM appointments WHERE appointment_date=? FOR UPDATE");$q->execute([$a['appointment_date']]);$number=(int)$q->fetchColumn();$up=$pdo->prepare("UPDATE appointments SET status='Waiting',queue_number=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status='Pending'");$up->execute([$number,$u['id'],$id]);$pdo->commit();flash('Appointment approved. Queue number assigned: Q-'.str_pad($number,3,'0',STR_PAD_LEFT).'.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Could not approve the appointment. Try again.','error');}
 } elseif($action==='reject' && $u['role']==='admin' && $a['status']==='Pending') {$up=$pdo->prepare("UPDATE appointments SET status='Rejected',reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status='Pending'");$up->execute([$u['id'],$id]);flash('Appointment rejected.');}
 elseif($action==='status' && in_array($u['role'],['admin','staff'],true)) {$next=$_POST['new_status']??'';$allowed=['Waiting','Serving','Completed','Cancelled'];if(in_array($next,$allowed,true) && in_array($a['status'],['Waiting','Serving','Approved'],true)){$up=$pdo->prepare('UPDATE appointments SET status=? WHERE id=?');$up->execute([$next,$id]);flash('Queue status updated to '.$next.'.');}else flash('That status change is not allowed.','error');}
 else flash('You do not have permission to do that.','error'); go('manage.php');
}
$filter=$_GET['status']??'All';$valid=['All','Pending','Waiting','Serving','Completed','Rejected','Cancelled'];if(!in_array($filter,$valid,true))$filter='All';
$sql='SELECT a.*,u.name AS student_name,u.email FROM appointments a JOIN users u ON u.id=a.user_id';$params=[];if($filter!=='All'){$sql.=' WHERE a.status=?';$params[]=$filter;}$sql.=" ORDER BY CASE a.status WHEN 'Pending' THEN 1 WHEN 'Waiting' THEN 2 WHEN 'Serving' THEN 3 ELSE 4 END,a.appointment_date,a.queue_number,a.created_at";$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();
$pending=(int)$pdo->query("SELECT COUNT(*) FROM appointments WHERE status='Pending'")->fetchColumn();$waiting=(int)$pdo->query("SELECT COUNT(*) FROM appointments WHERE status='Waiting'")->fetchColumn();$serving=(int)$pdo->query("SELECT COUNT(*) FROM appointments WHERE status='Serving'")->fetchColumn();layout_start('Queue management'); ?>
<div class="page-heading"><div><div class="eyebrow">STAFF WORKSPACE</div><h1>Queue & approvals</h1><p class="muted">Approve requests and update the live service status.</p></div></div>
<div class="stats-grid three"><div class="stat-card"><span>Pending approval</span><strong><?=$pending?></strong><small>Admin action needed</small></div><div class="stat-card"><span>Waiting</span><strong><?=$waiting?></strong><small>Assigned queue number</small></div><div class="stat-card"><span>Now serving</span><strong><?=$serving?></strong><small>In progress</small></div></div>
<div class="filter-row"><?php foreach($valid as $v): ?><a class="filter <?=($filter===$v?'active':'')?>" href="?status=<?=urlencode($v)?>"><?=e($v)?></a><?php endforeach; ?></div>
<div class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Student</th><th>Service</th><th>Date / time</th><th>Queue</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['student_name'])?></strong><div class="tiny muted"><?=e($r['email'])?></div></td><td><?=e($r['service'])?><div class="tiny muted"><?=e($r['notes']??'')?></div></td><td><?=e($r['appointment_date'])?><div class="tiny muted"><?=e(substr($r['appointment_time'],0,5))?></div></td><td><?=$r['queue_number']?'Q-'.str_pad($r['queue_number'],3,'0',STR_PAD_LEFT):'—'?></td><td><span class="status <?=strtolower($r['status'])?>"><?=e($r['status'])?></span></td><td class="actions"><?php if($u['role']==='admin' && $r['status']==='Pending'): ?><form method="post"><?php csrf_field(); ?><input type="hidden" name="appointment_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="approve"><button class="btn small">Approve</button></form><form method="post" onsubmit="return confirm('Reject this request?')"><?php csrf_field(); ?><input type="hidden" name="appointment_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="reject"><button class="btn small danger" name="action" value="reject">Reject</button></form><?php elseif(in_array($r['status'],['Waiting','Serving','Approved'],true)): ?><form method="post" class="inline-form"><?php csrf_field(); ?><input type="hidden" name="action" value="status"><input type="hidden" name="appointment_id" value="<?=$r['id']?>"><select name="new_status" aria-label="New status"><option value="">Change…</option><?php foreach(['Waiting','Serving','Completed','Cancelled'] as $st): if($st!==$r['status']): ?><option><?=e($st)?></option><?php endif; endforeach; ?></select><button class="btn small secondary">Save</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="center muted">No appointments found.</td></tr><?php endif; ?></tbody></table></div></div>
<?php layout_end(); ?>
